func siparisDetayText(_ text: String, lang: String) -> String {
    if let exact = siparisDetayLocalTranslations[text]?[lang] { return exact }
    if let english = siparisDetayLocalTranslations[text]?["English"] { return english }
    return t(text, lang: lang)
}


func t(_ text: String, lang: String) -> String {
    if let translated = studioFlowFeatureTranslations[text]?[lang] { return translated }
    if let translated = globalDilSozlugu[text]?[lang] { return translated }
    return text
}

func formatFiyat(_ val: Double, ondalik: String) -> String {
    let formatter = NumberFormatter(); formatter.numberStyle = .decimal; formatter.minimumFractionDigits = 2; formatter.maximumFractionDigits = 2; formatter.decimalSeparator = ondalik; formatter.groupingSeparator = ondalik == "," ? "." : ","
    return formatter.string(from: NSNumber(value: val)) ?? String(format: "%.2f", val).replacingOccurrences(of: ".", with: ondalik)
}
